settings.custom_css:
/* === BULLETPROOF GAP & CARD VISUAL === */
selector .aop-card-col { background: transparent !important; border-left: 12px solid transparent !important; border-right: 12px solid transparent !important; overflow: visible !important; }

/* FIXED HEIGHT CARD (Stable Row) */
selector .aop-card-col > .elementor-widget-wrap, selector .aop-card-col > .elementor-element-populated { 
  height: 520px !important; 
  position: relative !important; 
  border-radius: 20px !important; 
  overflow: hidden !important; 
  background: #0d0d0f !important; 
  padding: 28px 24px 32px 24px !important; 
  z-index: 1 !important; 
  box-shadow: 0 10px 30px rgba(0,0,0,0.5) !important; 
  transition: transform 0.4s ease, box-shadow 0.4s ease !important; 
}
@media(max-width:1024px){ selector .aop-card-col > .elementor-widget-wrap { height:480px !important; } }
@media(max-width:767px){ selector .aop-card-col > .elementor-widget-wrap { height:440px !important; } }

/* Interactive Card Lift */
selector .aop-card-col:hover > .elementor-widget-wrap, selector .aop-card-col:hover > .elementor-element-populated { transform: translateY(-8px) scale(1.01) !important; box-shadow: 0 30px 60px rgba(0,0,0,0.6) !important; }

/* === DARK GRADIENT OVERLAY === */
selector .aop-card-col > .elementor-widget-wrap::before, selector .aop-card-col > .elementor-element-populated::before { content: '' !important; position: absolute !important; inset: 0 !important; background: linear-gradient(to top, rgba(8,8,10,0.95) 0%, rgba(8,8,10,0.5) 45%, transparent 80%) !important; z-index: 2 !important; pointer-events: none !important; transition: background 0.4s ease !important; }
selector .aop-card-col:hover > .elementor-widget-wrap::before, selector .aop-card-col:hover > .elementor-element-populated::before { background: linear-gradient(to top, rgba(8,8,10,0.98) 0%, rgba(8,8,10,0.85) 50%, rgba(8,8,10,0.4) 80%, rgba(8,8,10,0.1) 100%) !important; }

/* === ROBUST SPACER TRANSITION (Pulls content up correctly) === */
selector .aop-flexible-spacer .elementor-spacer-inner { 
  height: 320px !important; 
  transition: height 0.45s cubic-bezier(0.23, 1, 0.32, 1) !important; 
}
@media(max-width:767px){ selector .aop-flexible-spacer .elementor-spacer-inner { height:180px !important; } }

selector .aop-card-col:hover .aop-flexible-spacer .elementor-spacer-inner { 
  height: 48px !important; 
}

/* === CONTENT WIDGETS ABOVE OVERLAY === */
selector .aop-card-col .elementor-widget:not(.aop-bg-video) { position: relative !important; z-index: 3 !important; text-align: left !important; }
selector .aop-card-col .elementor-heading-title, 
selector .aop-card-col .aop-tag, 
selector .aop-card-col .aop-deity { 
  text-align: left !important; 
  margin-left: 0 !important; 
}

/* === ABSOLUTE BACKGROUND VIDEO === */
selector .aop-bg-video { position: absolute !important; top: 0 !important; left: 0 !important; right: 0 !important; bottom: 0 !important; z-index: 0 !important; padding: 0 !important; margin: 0 !important; width: auto !important; height: auto !important; }
selector .aop-bg-video .elementor-widget-container, selector .aop-bg-video .elementor-video-container, selector .aop-bg-video .e-hosted-video { position: absolute !important; top: 0 !important; left: 0 !important; right: 0 !important; bottom: 0 !important; padding: 0 !important; margin: 0 !important; width: 100% !important; height: 100% !important; }
selector .aop-bg-video video, selector .aop-bg-video .elementor-video { object-fit: cover !important; width: 100% !important; height: 100% !important; display: block !important; margin: 0 !important; padding: 0 !important; transition: transform 0.6s ease !important; }
/* Video Hover Zoom */
selector .aop-card-col:hover .aop-bg-video video { transform: scale(1.05) !important; }

/* === DESCRIPTION REVEAL === */
selector .aop-desc-wrap { overflow: hidden !important; max-height: 0 !important; opacity: 0 !important; transition: max-height 0.45s cubic-bezier(0.23, 1, 0.32, 1), opacity 0.4s ease !important; }
selector .aop-card-col:hover .aop-desc-wrap { max-height: 180px !important; opacity: 1 !important; padding-top: 12px !important; }
selector .aop-desc-wrap p { color: #ffffff !important; text-shadow: 0 2px 4px rgba(0,0,0,0.8) !important; font-family:'Inter',sans-serif !important; font-size:13px !important; line-height:1.68 !important; margin:0 !important; }

/* === BUTTON REVEAL === */
selector .aop-btn-wrap { overflow: hidden !important; max-height: 0 !important; opacity: 0 !important; transition: max-height 0.35s cubic-bezier(0.23, 1, 0.32, 1), opacity 0.3s ease !important; }
selector .aop-card-col:hover .aop-btn-wrap { max-height: 64px !important; opacity: 1 !important; }
selector .aop-btn-wrap .elementor-button { font-family:'Inter',sans-serif !important; font-size:11px !important; font-weight:700 !important; letter-spacing:2.5px !important; text-transform:uppercase !important; color:#d4a853 !important; background:transparent !important; background-color:transparent !important; padding:16px 0 0 !important; border:none !important; box-shadow:none !important; }

/* === TAGS === */
selector .aop-tag { display:inline-block !important; font-family:'Inter',sans-serif !important; font-size:9px !important; font-weight:700 !important; letter-spacing:2.5px !important; text-transform:uppercase !important; color:rgba(212,168,83,.92) !important; border:1px solid rgba(212,168,83,.35) !important; padding:6px 14px !important; border-radius:999px !important; margin-bottom:10px !important; background:rgba(0,0,0,.3) !important; backdrop-filter:blur(4px); line-height:1 !important; }
selector .aop-deity { font-family:'Inter',sans-serif !important; font-size:10px !important; font-weight:700 !important; letter-spacing:2.5px !important; text-transform:uppercase !important; color:rgba(212,168,83,.75) !important; margin-bottom:8px !important; }

/* TABLET/MOBILE RESPONSIVENESS */
@media(max-width:900px){ selector .aop-card-col > .elementor-widget-wrap, selector .aop-card-col > .elementor-element-populated { padding: 20px 16px 24px 16px !important; } }
